14	// runEmbeddedServer starts an in-process NATS server on a random loopback port
15	// and returns its client URL. The server is shut down when the test ends.
16	func runEmbeddedServer(t *testing.T) string {
17		t.Helper()
18		s, err := natsserver.NewServer(&natsserver.Options{
19			Host:   "127.0.0.1",
20			Port:   -1, // pick a free port
21			NoLog:  true,
22			NoSigs: true,
23		})
24		if err != nil {
25			t.Fatalf("new embedded nats server: %v", err)
26		}
27		go s.Start()
28		if !s.ReadyForConnections(10 * time.Second) {
29			t.Fatal("embedded nats server not ready in time")
30		}
31		t.Cleanup(s.Shutdown)
32		return s.ClientURL()
33	}
