35	// capturingHandler is a thread-safe slog.Handler that records log messages so
36	// tests can assert what was logged, including from background goroutines.
37	type capturingHandler struct {
38		mu   sync.Mutex
39		msgs []string
40	}
41	
42	func (h *capturingHandler) Enabled(context.Context, slog.Level) bool { return true }
43	
44	func (h *capturingHandler) Handle(_ context.Context, r slog.Record) error {
45		h.mu.Lock()
46		h.msgs = append(h.msgs, r.Message)
47		h.mu.Unlock()
48		return nil
49	}
50	
51	func (h *capturingHandler) WithAttrs([]slog.Attr) slog.Handler { return h }
52	func (h *capturingHandler) WithGroup(string) slog.Handler      { return h }
53	
54	func (h *capturingHandler) has(msg string) bool {
55		h.mu.Lock()
56		defer h.mu.Unlock()
57		return slices.Contains(h.msgs, msg)
58	}
59	
60	func (h *capturingHandler) snapshot() []string {
61		h.mu.Lock()
62		defer h.mu.Unlock()
63		return slices.Clone(h.msgs)
64	}
65	
66	// waitFor blocks until a message equal to msg has been logged, or fails the
67	// test after a short deadline. Used to synchronize on logs emitted from a
68	// background loop goroutine.
69	func (h *capturingHandler) waitFor(t *testing.T, msg string) {
70		t.Helper()
71		deadline := time.Now().Add(2 * time.Second)
72		for time.Now().Before(deadline) {
73			if h.has(msg) {
74				return
75			}
76			time.Sleep(5 * time.Millisecond)
77		}
78		t.Fatalf("did not observe log %q; saw %v", msg, h.snapshot())
79	}
80	
81	// newCapturingLogger returns a logger writing to a fresh capturingHandler.
82	func newCapturingLogger() (*slog.Logger, *capturingHandler) {
83		h := &capturingHandler{}
84		return slog.New(h), h
85	}
