22	// TestProcessDispatchesDecodedEvent: a payload that decodes reaches handle with the
23	// decoded event and a live span; the message is left for handle to ack/nak (Process
24	// does not touch it), and onUndecodable is not called.
25	func TestProcessDispatchesDecodedEvent(t *testing.T) {
26		msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
27		var (
28			gotEv   string
29			gotSpan trace.Span
30			gotMsg  jetstream.Msg
31			dropped bool
32		)
33		decode := func(b []byte) (string, error) { return "decoded:" + string(b), nil }
34		handle := func(_ context.Context, span trace.Span, m jetstream.Msg, ev string) {
35			gotEv, gotSpan, gotMsg = ev, span, m
36		}
37		Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })
38	
39		if gotEv != "decoded:payload" {
40			t.Errorf("handle got ev %q, want decoded:payload", gotEv)
41		}
42		if gotSpan == nil {
43			t.Error("handle got a nil span, want the live consumer span")
44		}
45		if gotMsg != msg {
46			t.Error("handle got a different msg than the one passed to Process")
47		}
48		if msg.Acked || msg.Termed || msg.Naks > 0 || len(msg.NakDelays) > 0 {
49			t.Error("Process disposed the message, want none (handle owns ack/nak)")
50		}
51		if dropped {
52			t.Error("onUndecodable called on a successful decode")
53		}
54	}
