// validate rejects the configuration errors no retry can fix; shared by
// [Start] (one-shot) and [Run] (supervised, which must fail fast on these
// rather than retry them forever).
func (c Config) validate(nc *nats.Conn) error {
	if c.KeepInProgress && c.MaxMessages > 1 {
		return fmt.Errorf("jsconsumer(%s): KeepInProgress requires MaxMessages <= 1: the heartbeat extends only the in-flight delivery, so %d buffered messages would exhaust AckWait behind a long handler", c.Name, c.MaxMessages)
	}
	if c.Durable == "" {
		// CreateOrUpdateConsumer accepts an empty durable and silently makes
		// an ephemeral, server-named consumer — losing the stable
		// resume-across-restarts behavior this scaffold promises.
		return fmt.Errorf("jsconsumer(%s): Durable is required", c.Name)
	}
	if nc == nil {
		return fmt.Errorf("jsconsumer(%s): nil nats conn", c.Name)
	}
	return nil
}

func (c Config) tracer() trace.Tracer {

// Retry envelope for [Run]'s supervision: exponential from runRetryInitial
// doubling to runRetryMax, reset once a consume loop survives longer than the
// max. Package vars (not consts) so tests can compress the schedule.
var (
	runRetryInitial = time.Second
	runRetryMax     = 30 * time.Second
)

// Run supervises the consume loop [Start] builds. Where Start is one-shot —
// an error at consumer creation is returned, and a consume loop that closes
// underneath the caller (consumer deleted on the server, subscription
// invalidated) stays closed — Run retries both with exponential backoff
// (runRetryInitial doubling to runRetryMax, reset after a loop that outlives
// the max). In particular a stream that is not provisioned yet at boot — the
// declarative-provisioning race — is a retry, not a crash.
//
// Run blocks until ctx is cancelled, then joins the live loop (including an
// in-flight handler, see [Runner.Stop]) before returning, so it composes with
// the cancel → join → drain shutdown ordering as the body of a supervised
// goroutine:
//
//	g.Go(func(ctx context.Context) {
//		if err := jsconsumer.Run(ctx, nc, cfg, onMsg); err != nil {
//			log.Error("consumer config rejected", "error", err)
//		}
//	})
//
// Configuration errors — nil connection, empty Durable, the
// KeepInProgress/MaxMessages conflict — can never succeed on retry and are
// returned immediately; a nil return means a clean, ctx-driven exit.
func Run(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) error {
	if err := cfg.validate(nc); err != nil {
		return err
	}
	delay := runRetryInitial
	for {
		// Each attempt gets a child context so the cancel-watcher goroutine
		// Start arms is released when the attempt dies, instead of one
		// accumulating per recreate for the life of the process.
		attemptCtx, cancelAttempt := context.WithCancel(ctx)
		r, err := Start(attemptCtx, nc, cfg, onMsg)
		if err != nil {
			cancelAttempt()
			if ctx.Err() != nil {
				return nil
			}
			cfg.logger().WarnContext(ctx, cfg.Name+": start consumer failed; retrying",
				slog.Any("error", err), slog.Duration("retry_in", delay))
		} else {
			started := time.Now()
			select {
			case <-ctx.Done():
				r.Stop()
				cancelAttempt()
				return nil
			case <-r.closed:
				cancelAttempt()
				if ctx.Err() != nil {
					return nil
				}
				// A loop that ran long enough to be called healthy earns a
				// fresh envelope; a flapping one keeps escalating.
				if time.Since(started) >= runRetryMax {
					delay = runRetryInitial
				}
				cfg.logger().WarnContext(ctx, cfg.Name+": consume loop closed; recreating",
					slog.Duration("retry_in", delay))
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case <-time.After(delay):
		}
		delay = min(delay*2, runRetryMax)
	}
}

// Process runs the per-message prologue shared by every consumer: open the

// compressRunRetries shrinks Run's supervision envelope so recreate paths are
// exercised in milliseconds, restoring it when the test ends.
func compressRunRetries(t *testing.T) {
	t.Helper()
	origInitial, origMax := runRetryInitial, runRetryMax
	runRetryInitial, runRetryMax = 20*time.Millisecond, 100*time.Millisecond
	t.Cleanup(func() { runRetryInitial, runRetryMax = origInitial, origMax })
}

// runTestEnv boots an embedded JetStream server and a connection, returning
// the JetStream context for stream/consumer manipulation.
func runTestEnv(t *testing.T) (*nats.Conn, jetstream.JetStream) {
	t.Helper()
	url := runJetStreamServer(t)
	nc, err := nats.Connect(url)
	if err != nil {
		t.Fatalf("connect: %v", err)
	}
	t.Cleanup(nc.Close)
	js, err := jetstream.New(nc)
	if err != nil {
		t.Fatalf("jetstream.New: %v", err)
	}
	return nc, js
}

// TestRunRejectsInvalidConfig: configuration errors can never succeed on
// retry, so Run must return them immediately instead of supervising forever.
func TestRunRejectsInvalidConfig(t *testing.T) {
	if err := Run(context.Background(), nil, testCfg, func(jetstream.Msg) {}); err == nil || !strings.Contains(err.Error(), "Durable") {
		t.Fatalf("Run(empty Durable) err = %v, want immediate Durable-required error", err)
	}
}

// TestRunDeliversAndReturnsOnCancel: the supervised loop delivers like Start
// and exits nil once ctx is cancelled — the contract that lets it be the body
// of a ShutdownGroup.Go goroutine.
func TestRunDeliversAndReturnsOnCancel(t *testing.T) {
	nc, js := runTestEnv(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
		Name: "events_v1", Subjects: []string{"events.>"},
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}

	got := make(chan jetstream.Msg, 1)
	done := make(chan error, 1)
	cfg := Config{Stream: "events_v1", Durable: "run_durable", FilterSubject: "events.repo",
		Name: "testconsumer", SpanName: "test.consume"}
	go func() {
		done <- Run(ctx, nc, cfg, func(m jetstream.Msg) {
			if err := m.Ack(); err != nil {
				t.Errorf("ack: %v", err)
			}
			got <- m
		})
	}()

	if _, err := js.Publish(ctx, "events.repo", []byte("hello")); err != nil {
		t.Fatalf("publish: %v", err)
	}
	select {
	case m := <-got:
		if string(m.Data()) != "hello" {
			t.Errorf("payload = %q, want hello", m.Data())
		}
	case <-time.After(5 * time.Second):
		t.Fatal("message did not reach onMsg")
	}

	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("Run returned %v on cancel, want nil", err)
		}
	case <-time.After(10 * time.Second):
		t.Fatal("Run did not return after ctx cancel")
	}
}

// TestRunToleratesMissingStreamAtBoot: a stream that is not provisioned yet
// when the service boots (the declarative-provisioning race) is a retry, not
// a crash — once the stream appears, the consumer comes up and delivers.
func TestRunToleratesMissingStreamAtBoot(t *testing.T) {
	compressRunRetries(t)
	nc, js := runTestEnv(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	got := make(chan jetstream.Msg, 1)
	done := make(chan error, 1)
	cfg := Config{Stream: "late_v1", Durable: "late_durable", FilterSubject: "late.repo",
		Name: "testconsumer", SpanName: "test.consume"}
	go func() {
		done <- Run(ctx, nc, cfg, func(m jetstream.Msg) {
			if err := m.Ack(); err != nil {
				t.Errorf("ack: %v", err)
			}
			got <- m
		})
	}()

	// Let at least one create attempt fail against the absent stream.
	time.Sleep(60 * time.Millisecond)
	if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
		Name: "late_v1", Subjects: []string{"late.>"},
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}
	if _, err := js.Publish(ctx, "late.repo", []byte("finally")); err != nil {
		t.Fatalf("publish: %v", err)
	}
	select {
	case m := <-got:
		if string(m.Data()) != "finally" {
			t.Errorf("payload = %q, want finally", m.Data())
		}
	case <-time.After(5 * time.Second):
		t.Fatal("message did not arrive after the stream appeared")
	}

	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("Run returned %v on cancel, want nil", err)
		}
	case <-time.After(10 * time.Second):
		t.Fatal("Run did not return after ctx cancel")
	}
}

// TestRunRecreatesAfterConsumerDeleted: deleting the durable on the server is
// a terminal error for the live consume loop (nats.go stops it and Closed
// fires); Run must notice and recreate rather than leaving the service
// running but deaf.
func TestRunRecreatesAfterConsumerDeleted(t *testing.T) {
	compressRunRetries(t)
	nc, js := runTestEnv(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
		Name: "events_v1", Subjects: []string{"events.>"},
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}

	got := make(chan string, 2)
	done := make(chan error, 1)
	cfg := Config{Stream: "events_v1", Durable: "recreate_durable", FilterSubject: "events.repo",
		Name: "testconsumer", SpanName: "test.consume"}
	go func() {
		done <- Run(ctx, nc, cfg, func(m jetstream.Msg) {
			if err := m.Ack(); err != nil {
				t.Errorf("ack: %v", err)
			}
			got <- string(m.Data())
		})
	}()

	if _, err := js.Publish(ctx, "events.repo", []byte("one")); err != nil {
		t.Fatalf("publish: %v", err)
	}
	select {
	case m := <-got:
		if m != "one" {
			t.Fatalf("first delivery = %q, want one", m)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("first message did not arrive")
	}

	if err := js.DeleteConsumer(ctx, "events_v1", "recreate_durable"); err != nil {
		t.Fatalf("delete consumer: %v", err)
	}
	if _, err := js.Publish(ctx, "events.repo", []byte("two")); err != nil {
		t.Fatalf("publish: %v", err)
	}
	select {
	case m := <-got:
		if m != "two" {
			t.Fatalf("post-recreate delivery = %q, want two", m)
		}
	case <-time.After(10 * time.Second):
		t.Fatal("message did not arrive after the consumer was deleted and recreated")
	}

	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("Run returned %v on cancel, want nil", err)
		}
	case <-time.After(10 * time.Second):
		t.Fatal("Run did not return after ctx cancel")
	}
}

